// @vitest-environment node
import {it,expect,vi} from 'vitest';
import {buildCompleteAmbienceBundle as build} from './completeAmbienceBundle.js';
function fixture(){const output={disconnect:vi.fn()},context={createGain:vi.fn(()=>output)},facade={ready:Promise.resolve(),setShape:vi.fn(async()=>{}),setLevels:vi.fn(async()=>{}),setWander:vi.fn(async()=>{}),prepare:vi.fn(async()=>{}),whenIdle:vi.fn(async()=>{}),connect:vi.fn(async()=>{}),checkRuntime:vi.fn(),status:()=>({error:null}),running:false,dispose:vi.fn(async()=>({clean:true,acknowledged:true}))},environment={context,ambienceFactory:vi.fn(()=>facade),prepareAmbienceStart:vi.fn(),checkRuntime:vi.fn()},settings={ambience:{rain:.2},ambienceShape:{},ambienceWander:{mode:'brownian'}};return{context,output,facade,environment,settings};}
it('returns a stopped detached component/output and explicit prepared-start callback without publishing any old runtime pointer',async()=>{const f=fixture(),owner=await build(f);expect(owner.ambience).toBe(f.facade);expect(owner.output).toBe(f.output);expect(f.facade.connect).toHaveBeenCalledWith(f.output);expect(owner.describe().stopped).toBe(true);owner.check();owner.prepareStart({offset:0});expect(f.environment.prepareAmbienceStart).toHaveBeenCalledWith(f.facade,{offset:0});const result=owner.dispose();expect(owner.dispose()).toBe(result);expect((await result).clean).toBe(true);expect(f.output.disconnect).toHaveBeenCalledOnce();});
it('cleans partial facade/output owners on cancellation and still disconnects output when source cleanup rejects',async()=>{const f=fixture(),controller=new AbortController();f.facade.setLevels.mockImplementation(async()=>controller.abort());await expect(build({...f,signal:controller.signal})).rejects.toMatchObject({name:'AbortError',diagnostics:{completeAmbienceBundleCleanup:[{clean:true,acknowledged:true}]}});expect(f.output.disconnect).toHaveBeenCalledOnce();const b=fixture(),owner=await build(b);b.facade.dispose.mockRejectedValue(Error('actual uncertain source cleanup'));await expect(owner.dispose()).rejects.toThrow('uncertain source');expect(b.output.disconnect).toHaveBeenCalledOnce();});
it('rejects an active candidate during stopped preflight and refuses wrong environment context before construction',async()=>{const f=fixture(),owner=await build(f);f.facade.running=true;expect(()=>owner.check()).toThrow('remain stopped');await owner.dispose();const b=fixture();await expect(build({...b,context:{createGain:vi.fn()}})).rejects.toThrow('contract');expect(b.environment.ambienceFactory).not.toHaveBeenCalled();});
